<?php /** @var array $privacy @var array $requests @var \Core\Security\Csrf $csrf */ ?>
<div class="card"><h2 style="margin-top:0">Consent and analytics</h2><p class="muted">Analytics code is never loaded until a visitor explicitly allows it.</p><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="settings"><label><input type="checkbox" style="width:auto" name="banner_enabled" value="1" <?= $privacy['banner_enabled']?'checked':'' ?>> Show cookie choice banner</label><div class="inline-fields"><div><label>Analytics provider</label><select name="provider"><?php foreach(['none'=>'None','ga4'=>'Google Analytics 4','plausible'=>'Plausible'] as $v=>$l): ?><option value="<?= e_attr($v) ?>" <?= $privacy['provider']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></div><div><label>Measurement ID / domain</label><input name="site_id" value="<?= e_attr($privacy['site_id']) ?>" placeholder="G-XXXXXXXX or example.com"></div><button class="btn" style="align-self:end">Save</button></div></form></div>
<div class="card"><div class="card-heading"><h2 style="margin-top:0">Privacy requests</h2><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/privacy/export">Export CSV</a></div><?php if(!$requests): ?><div class="empty-state">No privacy requests.</div><?php else: ?><table><tr><th>Received</th><th>Request</th><th>Email / details</th><th>Status</th><th></th></tr><?php foreach($requests as $item): ?><tr><td><?= e($item['created_at']) ?></td><td><?= e($item['request_type']) ?></td><td><strong><?= e($item['email']) ?></strong><br><span class="muted"><?= nl2br(e($item['details']??'')) ?></span></td><td><span class="badge <?= $item['status']==='completed'?'ok':'warn' ?>"><?= e($item['status']) ?></span></td><td><?php if($item['status']!=='completed'): ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn small">Mark completed</button></form><?php endif; ?></td></tr><?php endforeach; ?></table><?php endif; ?></div>
